INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Maximumprinzip immer maximale Kosten bedeutet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Fokussiert auf Effizienz"}, {"text": "Ja", "correct": false, "because": "Kosten nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich das Maximumprinzip auf ein IT-System anwende?', 3, '[{"text": "Ressourcennutzung", "correct": true, "because": "Maximiert Effizienz"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Optimierung zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zum Maximumprinzip in der IT?', 5, '[{"text": "Leistungsoptimierung", "correct": true, "because": "Maximiert Output"}, {"text": "Kosteneffizienz", "correct": true, "because": "Nutzt Ressourcen optimal"}, {"text": "Büromöbel", "correct": false, "because": "Kein IT-Faktor"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Maximumprinzip zielt auf höchste Effizienz ab. b) Es ignoriert Kosten immer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich das Maximumprinzip in einem IT-System anwende?', 4, '[{"text": "Systemleistung", "correct": false, "because": "Wichtiger Faktor"}, {"text": "Ressourcenverbrauch", "correct": false, "because": "Zu maximieren"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Optimierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Maximumprinzip nur für Hardware gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software relevant"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Maximumprinzip in der IT?', 3, '[{"text": "Optimale Leistung", "correct": true, "because": "Maximiert Effizienz"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Optimierung zählt"}, {"text": "Weniger Ressourcen", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen das Maximumprinzip in der IT?', 5, '[{"text": "Lastverteilung", "correct": true, "because": "Optimiert Ressourcen"}, {"text": "Performance-Tuning", "correct": true, "because": "Steigert Leistung"}, {"text": "Büroplanung", "correct": false, "because": "Irrelevant"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das Maximumprinzip maximiert Ressourcennutzung. b) Es ist immer ineffizient. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Effizienz ist Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um das Maximumprinzip in der IT anzuwenden?', 4, '[{"text": "Leistungsmetriken", "correct": false, "because": "Messen Effizienz"}, {"text": "Optimierungstools", "correct": false, "because": "Unterstützen Prozess"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Optimierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Maximumprinzip immer auf Hardware beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software optimierbar"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Maximumprinzip in der IT?', 4, '[{"text": "Höhere Effizienz", "correct": true, "because": "Maximiert Leistung"}, {"text": "Kostensenkung", "correct": true, "because": "Optimiert Ressourcen"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Maximumprinzip nur für große IT-Systeme gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Systeme"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um das Maximumprinzip in einem IT-System umzusetzen?', 3, '[{"text": "Monitoring-Tools", "correct": true, "because": "Messen Leistung"}, {"text": "Schnellste Software", "correct": false, "because": "Optimierung zählt"}, {"text": "Bunte Oberfläche", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Maximumprinzip kann Kosten senken. b) Es ignoriert Effizienz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Effizienz ist Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich beim Maximumprinzip in der IT?', 5, '[{"text": "Ressourcenverbrauch", "correct": true, "because": "Zu maximieren"}, {"text": "Systemleistung", "correct": true, "because": "Optimiert Output"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich das Maximumprinzip in einem IT-System anwende?', 3, '[{"text": "Leistungsmetriken", "correct": false, "because": "Messen Effizienz"}, {"text": "Optimierungsstrategien", "correct": false, "because": "Steigern Output"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Optimierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Maximumprinzip immer auf Leistung beschränkt?', 3, '[{"text": "Nein", "correct": true, "because": "Auch Kosten relevant"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
